package httpserver

import (
	"io"
	"net/http"
)

func renderBillingWorkspace(w http.ResponseWriter) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = io.WriteString(w, billingDemoPage)
}

func billingDemoScript(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
	_, _ = io.WriteString(w, billingDemoJavaScript)
}

const billingDemoPage = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>开票登记工作区</title><style>` + billingDemoCSS + `[hidden]{display:none!important}</style></head><body>
<p hidden>金额已按权限隐藏</p>
<header class="top"><a class="brand" href="./"><span>BI</span><div><strong>开票登记</strong><small>Billing / Invoice</small></div></a><div class="credential"><span id="credentialState">尚未连接</span><button id="refreshPermissions" class="quiet">刷新权限</button><button id="openCredential" class="quiet">设置访问凭证</button></div></header>
<div class="shell"><aside class="rail"><div><p class="eyebrow">票据事实</p><h1>已开票登记</h1><p class="intro">登记现实中已经开出的票据，保留来源快照、文件引用和每次纠错历史。</p></div><div class="filters"><label>状态<select id="statusFilter"><option value="">全部状态</option><option value="recorded">有效登记</option><option value="registration_invalidated">登记无效</option></select></label><label>Project ID（可选）<input id="projectFilter" placeholder="按 Project 收敛范围"></label><button id="applyFilters" class="quiet">应用筛选</button></div><div class="rail-actions"><button id="newRegistration" class="primary">登记已开票</button><button id="refreshList" class="quiet">刷新记录</button></div><section class="summary"><span>当前有效开票</span><strong id="totalAmount">按权限显示</strong><small id="recordCount">尚未读取</small></section><div id="listActions" class="action-chips"></div><div id="registrationList" class="record-list"><div class="empty">连接后显示开票登记。</div></div><div class="boundary"><strong>事实边界</strong><span>这里只记录“已经开票”的事实，不代替开票申请、税务平台、应收义务或实际回款。</span></div></aside>
<main><div id="notice" class="notice" role="status">正在准备工作区……</div><aside id="accessRecovery" class="recovery" hidden><div><strong>权限上下文已经变化</strong><span>页面已退出编辑状态；已读事实保留，旧能力不会继续使用。</span></div><a href="../workbench/">返回统一工作台</a></aside><aside id="faultRecovery" class="recovery fault" hidden><div><strong id="faultTitle">本次操作没有写入</strong><span id="faultMessage">当前投影与输入已保留。</span></div><div class="recovery-actions"><button id="retryCommand" class="quiet" hidden>使用原命令安全重试</button><button id="reloadLatest" class="primary">载入最新 revision</button></div></aside>
<section id="workspaceEmpty" class="empty-workspace"><div class="empty-mark">BI</div><h2>选择一条开票登记</h2><p>这里会显示票据双方、来源快照、金额可见性、Evidence 引用、允许动作和不可变历史。</p></section>
<section id="workspace" hidden><header class="workspace-head"><div><div class="status-line"><span id="status" class="status"></span><span id="amountVisibility" class="status quiet-status"></span></div><h2 id="workspaceTitle">开票登记</h2><code id="identity"></code></div><button id="reload" class="quiet">重新载入</button></header>
<dl class="facts"><div><dt>开票日期</dt><dd id="issuedOn"></dd></div><div><dt>金额</dt><dd id="amount"></dd></div><div><dt>当前 revision</dt><dd id="revision"></dd></div><div><dt>最近更新</dt><dd id="updatedAt"></dd></div></dl><div><p class="eyebrow">当前允许动作</p><div id="detailActions" class="action-chips"></div></div>
<nav class="tabs" aria-label="登记详情"><button class="tab active" data-pane="overview">登记事实</button><button class="tab" data-pane="evidence">票据文件</button><button class="tab" data-pane="history">变更历史</button></nav>
<section id="overview" class="pane active"><div class="section-head"><div><h3>登记事实与来源</h3><p>Party 和业务来源以稳定 ID、来源 revision 与当时快照保存。</p></div><button id="openCorrection" class="primary">纠正登记</button></div><div class="party-grid"><article><span>开票方</span><strong id="issuerName"></strong><code id="issuerMeta"></code></article><article><span>收票方</span><strong id="recipientName"></strong><code id="recipientMeta"></code></article></div><div class="source-block"><h4>业务来源快照</h4><div id="sourceList" class="source-list"></div></div><div class="note-block"><span>备注</span><p id="note"></p></div><p id="correctionDenied" class="permission-note" hidden>当前能力或状态不允许纠正登记。</p><div id="invalidateZone" class="danger-zone"><div><strong>标记系统登记无效</strong><span>只撤销本系统中的登记，不冒充现实票据作废、红冲或退票。</span></div><button id="openInvalidation" class="danger">登记无效</button></div></section>
<section id="evidence" class="pane"><div class="section-head"><div><h3>票据文件引用</h3><p>文件字节由 Evidence Service 管理；Billing 只保存 File ID、Version、用途和显示名称。</p></div></div><div id="evidenceList" class="evidence-list"></div><form id="evidenceForm" class="action-form"><h4>替换完整引用集合</h4><p class="form-note">每行格式：File ID | Version | 用途 | 显示名称。用途为 invoice_document 或 supporting_material；留空会清除引用。</p><label>Evidence 引用<textarea name="refs" rows="5" placeholder="UUID | 1 | invoice_document | 电子发票.pdf"></textarea></label><label>变更原因<textarea name="reason" rows="3" required></textarea></label><button class="primary" type="submit">保存文件引用</button></form><p id="evidenceDenied" class="permission-note" hidden>当前能力或状态不允许管理文件引用。</p></section>
<section id="history" class="pane"><div class="section-head"><div><h3>不可变变更历史</h3><p>登记、纠正、文件变化和登记无效都会追加 revision，不覆盖旧事实。</p></div><button id="loadHistory" class="quiet">读取历史</button></div><div id="historyList" class="timeline"><div class="empty">尚未读取历史。</div></div><p id="historyDenied" class="permission-note" hidden>当前凭证没有读取历史的能力。</p></section></section></main></div>
<dialog id="credentialDialog"><form id="credentialForm"><p class="eyebrow">访问控制</p><h2>连接受保护业务 API</h2><p>独立开发可粘贴模板 Token；正式组合由 Gateway 使用 IAM Session 签发 HttpOnly 短期能力凭证。</p><label>Bearer Token<textarea id="token" rows="5" required></textarea></label><div class="dialog-actions"><button type="button" data-close="credentialDialog" class="quiet">取消</button><button class="primary" type="submit">保存并连接</button></div></form></dialog>
<dialog id="createDialog"><form id="createForm"><p class="eyebrow">登记已开票事实</p><h2>新建开票登记</h2><p>金额使用最小货币单位保存；Party 与来源必须引用精确 revision。</p><div class="form-grid"><label>开票日期<input name="issued_on" type="date" required></label><label>金额（元）<input name="amount" inputmode="decimal" placeholder="12500.00" required></label><label>币种<input name="currency" value="CNY" maxlength="3" required></label><label>开票方 Party ID<input name="issuer_id" required></label><label>开票方 revision<input name="issuer_revision" type="number" min="1" value="1" required></label><label>收票方 Party ID<input name="recipient_id" required></label><label>收票方 revision<input name="recipient_revision" type="number" min="1" value="1" required></label><label>来源类型<select name="source_kind"><option value="manual_confirmation">人工确认</option><option value="project">Project</option><option value="contract">合同</option><option value="settlement">结算</option><option value="money_obligation">资金义务</option></select></label><label id="sourceResourceField" hidden>来源资源 ID<input name="source_resource_id"></label><label id="sourceRevisionField" hidden>来源 revision<input name="source_revision" type="number" min="1" value="1"></label><label id="manualSummaryField" class="wide">人工确认说明<input name="manual_summary" value="纸质或电子票据已人工核对" required></label><label class="wide">备注<textarea name="note" rows="3"></textarea></label></div><div class="dialog-actions"><button type="button" data-close="createDialog" class="quiet">取消</button><button class="primary" type="submit">建立登记</button></div></form></dialog>
<dialog id="correctionDialog"><form id="correctionForm"><p class="eyebrow">显式纠错</p><h2>追加一条纠正 revision</h2><p>不会改写旧版本。金额无查看能力时，页面不会呈现或提交金额字段。</p><label>开票日期<input name="issued_on" type="date"></label><label id="correctionAmountField">金额（元）<input name="amount" inputmode="decimal"></label><label>备注<textarea name="note" rows="3"></textarea></label><label>纠正原因<textarea name="reason" rows="3" required></textarea></label><div class="dialog-actions"><button type="button" data-close="correctionDialog" class="quiet">取消</button><button class="primary" type="submit">提交纠正</button></div></form></dialog>
<dialog id="invalidationDialog"><form id="invalidationForm"><p class="eyebrow danger-text">高风险动作</p><h2>确认标记登记无效</h2><p>登记转为只读并从有效金额汇总中排除；历史与来源快照继续保留。</p><label>原因<textarea name="reason" rows="3" required></textarea></label><div class="dialog-actions"><button type="button" data-close="invalidationDialog" class="quiet">返回</button><button class="danger" type="submit">确认登记无效</button></div></form></dialog>
<script src="assets/demo.js"></script></body></html>`

const billingDemoCSS = `:root{font-family:Inter,"PingFang SC","Microsoft YaHei",ui-sans-serif,system-ui,sans-serif;color:#18212f;background:#f7f8fa;line-height:1.5;--ink:#18212f;--muted:#687586;--line:#e2e6eb;--strong:#b9c1cc;--surface:#fff;--soft:#f7f8fa;--accent:#3157a4;--accent-soft:#edf2fc;--danger:#a93a33;--success:#26734d;--warning:#8a5a00}*{box-sizing:border-box}body{margin:0}.top{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 30px;background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:5}.brand{display:flex;align-items:center;gap:12px;color:var(--ink);text-decoration:none}.brand>span{display:grid;place-items:center;width:36px;height:36px;border-radius:7px;background:var(--ink);color:#fff;font-size:11px;font-weight:800}.brand div{display:grid}.brand small{color:var(--muted);font-size:10px;letter-spacing:.08em;text-transform:uppercase}.credential,.rail-actions,.status-line,.dialog-actions,.recovery-actions{display:flex;align-items:center;gap:9px}.credential{color:var(--muted);font-size:12px}.shell{display:grid;grid-template-columns:340px minmax(0,1fr);min-height:calc(100vh - 64px)}.rail{display:flex;flex-direction:column;gap:18px;padding:28px 22px;background:#fff;border-right:1px solid var(--line)}.rail h1{margin:0 0 5px;font-size:27px;letter-spacing:-.03em}.eyebrow{margin:0 0 7px;color:var(--accent);font-size:10px;font-weight:800;letter-spacing:.15em;text-transform:uppercase}.intro{margin:0;color:var(--muted);font-size:13px}.filters{display:grid;gap:9px;padding:13px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.filters label{display:grid;gap:4px;color:var(--muted);font-size:11px}.filters input,.filters select{width:100%;padding:8px 9px;border:1px solid var(--strong);border-radius:5px;background:#fff;font:inherit;font-size:12px}.rail-actions>*{flex:1}.primary,.quiet,.danger{border:1px solid transparent;border-radius:6px;padding:9px 12px;font:inherit;font-size:12px;font-weight:700;cursor:pointer}.primary{background:var(--accent);color:#fff}.quiet{background:#fff;border-color:var(--strong);color:var(--ink)}.danger{background:var(--danger);color:#fff}.primary:hover{background:#28498b}.quiet:hover{border-color:var(--accent);color:var(--accent)}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid #2f6fdb;outline-offset:2px}.summary{display:grid;gap:2px;padding:12px 13px;border-left:3px solid var(--accent);background:var(--accent-soft)}.summary span,.summary small{color:var(--muted);font-size:11px}.summary strong{font-size:20px}.record-list{display:grid;border-top:1px solid var(--line)}.record{display:grid;gap:3px;width:100%;padding:12px 4px;border:0;border-bottom:1px solid var(--line);background:#fff;color:var(--ink);text-align:left;cursor:pointer}.record:hover,.record.active{background:var(--soft)}.record.active{box-shadow:inset 3px 0 var(--accent);padding-left:11px}.record strong{font-size:13px}.record span{color:var(--muted);font-size:11px}.action-chips{display:flex;flex-wrap:wrap;gap:6px}.action-chip{padding:3px 7px;border:1px solid var(--line);border-radius:999px;background:#fff;color:#566273;font-size:10px}.boundary{display:grid;gap:4px;margin-top:auto;padding:13px;border-top:1px solid var(--line);color:var(--muted);font-size:11px}.boundary strong{color:var(--ink)}main{min-width:0;padding:28px 32px 52px}.notice{min-height:36px;margin-bottom:14px;padding:9px 12px;border-left:3px solid var(--accent);background:#fff;color:var(--muted);font-size:12px}.notice.ok{border-color:var(--success);color:var(--success)}.notice.error{border-color:var(--danger);color:var(--danger)}.recovery{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:16px;padding:14px 16px;border:1px solid #dfc77b;background:#fff8df}.recovery div:first-child{display:grid;gap:3px}.recovery span{color:#6a5b2e;font-size:11px}.recovery a{color:var(--accent);font-size:12px;font-weight:700}.fault{border-color:#e0b0ad;background:#fff5f4}.empty-workspace{display:grid;place-items:center;align-content:center;min-height:520px;text-align:center}.empty-workspace p{max-width:560px;color:var(--muted)}.empty-mark{display:grid;place-items:center;width:70px;height:70px;border:1px solid var(--line);border-radius:10px;color:var(--accent);font-weight:850;letter-spacing:.08em}.workspace-head,.section-head,.danger-zone{display:flex;align-items:center;justify-content:space-between;gap:20px}.workspace-head{padding-bottom:18px;border-bottom:1px solid var(--line);animation:reveal .24s ease}.workspace-head h2{margin:6px 0 2px;font-size:26px}.workspace-head code{color:var(--muted);font-size:11px}.status{display:inline-flex;padding:3px 8px;border-radius:999px;background:var(--accent-soft);color:var(--accent);font-size:10px;font-weight:800}.quiet-status{background:#eef1f4;color:#566273}.facts{display:grid;grid-template-columns:1fr 1.4fr .7fr 1.3fr;margin:22px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.facts div{padding:13px 16px;border-right:1px solid var(--line)}.facts div:last-child{border-right:0}.facts dt{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.08em}.facts dd{margin:3px 0 0;overflow-wrap:anywhere;font-size:13px;font-weight:700}.tabs{display:flex;margin-top:23px;border-bottom:1px solid var(--line)}.tab{padding:11px 14px;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--muted);font:inherit;font-size:12px;cursor:pointer}.tab.active{border-color:var(--accent);color:var(--accent);font-weight:800}.pane{display:none;padding-top:22px;animation:reveal .18s ease}.pane.active{display:block}.section-head h3{margin:0;font-size:18px}.section-head p{margin:3px 0 0;color:var(--muted);font-size:12px}.party-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:17px}.party-grid article{display:grid;gap:5px;padding:16px;border:1px solid var(--line);border-radius:7px;background:#fff}.party-grid span,.note-block span{color:var(--muted);font-size:11px}.party-grid code{color:var(--muted);font-size:10px;overflow-wrap:anywhere}.source-block,.note-block{margin-top:20px;padding-top:16px;border-top:1px solid var(--line)}.source-block h4{margin:0 0 10px}.source-list,.evidence-list{display:grid;border-top:1px solid var(--line)}.source-row,.evidence-row{display:grid;grid-template-columns:1fr 1.4fr auto;gap:16px;padding:11px 4px;border-bottom:1px solid var(--line);font-size:12px}.source-row span,.evidence-row span{color:var(--muted)}.note-block p{margin:4px 0}.permission-note{padding:11px;border-left:3px solid var(--strong);background:#eef1f4;color:var(--muted);font-size:11px}.danger-zone{margin-top:20px;padding-top:16px;border-top:1px solid #e6c8c6}.danger-zone div{display:grid;gap:3px}.danger-zone span,.danger-text{color:var(--danger);font-size:11px}.action-form{display:grid;gap:11px;margin-top:16px;padding:18px;border:1px solid var(--line);border-radius:7px;background:#fff}.action-form h4{margin:0}.action-form label,dialog label{display:grid;gap:5px;color:#515d6c;font-size:11px;font-weight:700}.action-form input,.action-form textarea,.action-form select,dialog input,dialog textarea,dialog select{width:100%;padding:9px 10px;border:1px solid var(--strong);border-radius:5px;background:#fff;color:var(--ink);font:inherit;font-size:12px}.form-note{margin:0;color:var(--muted);font-size:11px}.timeline{display:grid;gap:9px;margin-top:14px}.event{display:grid;grid-template-columns:1fr auto;gap:4px 16px;padding:11px 13px;border-left:2px solid var(--accent);background:#fff}.event strong{font-size:12px}.event span{color:var(--muted);font-size:10px}.event p{grid-column:1/-1;margin:0;color:var(--muted);font-size:11px}.empty{padding:18px;color:var(--muted);font-size:12px;text-align:center}dialog{width:min(650px,calc(100% - 30px));border:1px solid var(--line);border-radius:10px;padding:24px;box-shadow:0 28px 85px #18212f2a}dialog::backdrop{background:#18212f99}dialog h2{margin:0 0 7px}dialog p:not(.eyebrow){color:var(--muted);font-size:12px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px;margin-top:15px}.form-grid .wide{grid-column:1/-1}.dialog-actions{justify-content:flex-end;margin-top:18px}@keyframes reveal{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}@media(prefers-reduced-motion:reduce){*{animation-duration:0s!important}}@media(max-width:980px){.shell{grid-template-columns:290px minmax(0,1fr)}.facts{grid-template-columns:repeat(2,1fr)}.facts div:nth-child(2){border-right:0}.facts div:nth-child(-n+2){border-bottom:1px solid var(--line)}}@media(max-width:760px){.top{height:auto;min-height:64px;padding:10px 15px}.credential{flex-wrap:wrap;justify-content:flex-end}.credential span{display:none}.shell{grid-template-columns:1fr}.rail{border-right:0;border-bottom:1px solid var(--line)}main{padding:22px 18px}.facts,.party-grid,.form-grid{grid-template-columns:1fr}.form-grid .wide{grid-column:auto}.facts div{border-right:0;border-bottom:1px solid var(--line)}.source-row,.evidence-row{grid-template-columns:1fr}.section-head,.danger-zone,.recovery{align-items:flex-start;flex-direction:column}.tabs{overflow:auto}}`

const billingDemoJavaScript = `(()=>{'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],suiteBase=location.pathname==='/'?'':location.pathname.replace(/\/$/,''),params=new URLSearchParams(location.search),state={token:sessionStorage.getItem('billing-demo-token')||'',items:[],listActions:[],details:null,pending:null,submitting:false};
const uuid=()=>crypto.randomUUID(),actions=()=>state.details?.allowed_actions||[],can=a=>actions().includes(a),canList=a=>state.listActions.includes(a),fmt=v=>v?new Date(v).toLocaleString('zh-CN'):'—',statusLabel={recorded:'有效登记',registration_invalidated:'登记无效'},eventLabel={recorded:'建立登记',details_corrected:'纠正资料',evidence_changed:'文件引用变化',registration_invalidated:'登记无效'};
function notice(message,type=''){const n=$('#notice');n.textContent=message;n.className='notice '+type}
function pane(id){$$('.pane').forEach(x=>x.classList.toggle('active',x.id===id));$$('.tab').forEach(x=>x.classList.toggle('active',x.dataset.pane===id))}
function errorOf(response,data){const code=data.error?.code||'HTTP_'+response.status,e=new Error(code);e.status=response.status;e.code=code;e.retryable=!!data.error?.retryable;return e}
async function api(path,opt={}){const headers={...(opt.headers||{})};if(state.token)headers.Authorization='Bearer '+state.token;if(opt.body&&!headers['Content-Type'])headers['Content-Type']='application/json';const response=await fetch(suiteBase+path,{credentials:'same-origin',...opt,headers});const text=await response.text();let data={};try{data=text?JSON.parse(text):{}}catch{const e=new Error(response.redirected?'需要从统一工作台重新进入应用':'服务返回了无法识别的内容');e.status=response.status;throw e}if(!response.ok)throw errorOf(response,data);return data}
function money(minor,currency){if(minor===null||minor===undefined)return'金额已按权限隐藏';const sign=minor<0?'-':'',absolute=Math.abs(minor),major=Math.floor(absolute/100),cents=String(absolute%100).padStart(2,'0');return sign+major.toLocaleString('zh-CN')+'.'+cents+' '+(currency||'')}
function minorInput(minor){return(Math.trunc(minor/100))+'.'+String(Math.abs(minor%100)).padStart(2,'0')}
function toMinor(value){const raw=String(value).trim();if(!/^\d+(\.\d{1,2})?$/.test(raw))throw new Error('金额最多保留两位小数');const parts=raw.split('.');return Number(parts[0])*100+Number((parts[1]||'').padEnd(2,'0'))}
function labelAction(value){return({read:'读取',record:'登记',amount_read:'查看金额',correct:'纠正',registration_invalidate:'登记无效',evidence_manage:'管理文件',history_read:'读取历史'})[value]||value}
function renderChips(target,values){const root=$(target);root.replaceChildren();(values||[]).forEach(value=>{const chip=document.createElement('span');chip.className='action-chip';chip.textContent=labelAction(value);root.append(chip)});if(!root.children.length){const chip=document.createElement('span');chip.className='action-chip';chip.textContent='当前无可用业务动作';root.append(chip)}}
function makeRecord(item){const button=document.createElement('button');button.className='record'+(state.details?.id===item.id?' active':'');const title=document.createElement('strong'),meta=document.createElement('span'),parties=document.createElement('span');title.textContent=(item.issuer_party?.legal_name||'未知开票方')+' → '+(item.recipient_party?.legal_name||'未知收票方');meta.textContent=(statusLabel[item.status]||item.status)+' · '+money(item.amount_minor,item.currency);parties.textContent=item.issued_on+' · revision '+item.revision;button.append(title,meta,parties);button.onclick=()=>openRegistration(item.id);return button}
function renderList(){const root=$('#registrationList');root.replaceChildren();if(!state.items.length){const empty=document.createElement('div');empty.className='empty';empty.textContent=canList('record')?'当前筛选没有记录，可以登记一张已经开出的票据。':'当前权限范围内没有可查看记录。';root.append(empty)}else state.items.forEach(x=>root.append(makeRecord(x)));$('#newRegistration').hidden=!canList('record');$('#recordCount').textContent=state.items.length+' 条当前记录';renderChips('#listActions',state.listActions)}
function listQuery(){const query=new URLSearchParams({limit:'50'}),status=$('#statusFilter').value,project=$('#projectFilter').value.trim()||params.get('project_id')||'';if(status)query.set('status',status);if(project)query.set('project_id',project);return query.toString()}
async function loadList(){try{notice('正在读取登记与服务端权限…');const data=await api('/api/v1/invoice-registrations?'+listQuery());state.items=data.items||[];state.listActions=data.allowed_actions||[];$('#totalAmount').textContent=data.effective_amount_minor===null||data.effective_amount_minor===undefined?'金额汇总已隐藏':money(data.effective_amount_minor,data.currency);renderList();$('#accessRecovery').hidden=true;notice('已读取 '+state.items.length+' 条记录；动作按最新 allowed_actions 收敛。','ok');const requested=params.get('invoice_registration_id');if(requested&&!state.details)await openRegistration(requested)}catch(error){state.items=[];state.listActions=[];$('#totalAmount').textContent='不可用';renderList();recover(error)}}
function addTextRow(root,values,emptyText){root.replaceChildren();if(!values.length){const empty=document.createElement('div');empty.className='empty';empty.textContent=emptyText;root.append(empty);return}values.forEach(value=>{const row=document.createElement('div'),name=document.createElement('strong'),meta=document.createElement('span'),tail=document.createElement('span');row.className=root.id==='sourceList'?'source-row':'evidence-row';if(root.id==='sourceList'){name.textContent=value.display_summary||value.kind;meta.textContent=(value.source_application||'人工确认')+' · '+value.kind;tail.textContent=value.resource_id?value.resource_id+' · r'+value.source_revision:'确认人 '+value.confirmed_by}else{name.textContent=value.display_name||value.file_id;meta.textContent=value.purpose;tail.textContent='v'+value.version+' · '+value.file_id}row.append(name,meta,tail);root.append(row)})}
function evidenceLines(values){return(values||[]).map(x=>[x.file_id,x.version,x.purpose,x.display_name||''].join(' | ')).join('\n')}
function renderDetails(){const d=state.details;$('#workspaceEmpty').hidden=true;$('#workspace').hidden=false;$('#status').textContent=statusLabel[d.status]||d.status;$('#amountVisibility').textContent=d.amount_visible?'金额可见':'金额已收敛';$('#workspaceTitle').textContent=(d.issuer_party?.legal_name||'开票方')+' → '+(d.recipient_party?.legal_name||'收票方');$('#identity').textContent=d.id;$('#issuedOn').textContent=d.issued_on;$('#amount').textContent=money(d.amount_minor,d.currency);$('#revision').textContent=String(d.revision);$('#updatedAt').textContent=fmt(d.updated_at);$('#issuerName').textContent=d.issuer_party?.legal_name||'—';$('#issuerMeta').textContent=(d.issuer_party?.id||'')+' · r'+(d.issuer_party?.revision||'');$('#recipientName').textContent=d.recipient_party?.legal_name||'—';$('#recipientMeta').textContent=(d.recipient_party?.id||'')+' · r'+(d.recipient_party?.revision||'');$('#note').textContent=d.note||'无备注';addTextRow($('#sourceList'),d.source_refs||[],'没有来源快照');addTextRow($('#evidenceList'),d.evidence_refs||[],'尚未登记票据文件');renderChips('#detailActions',actions());$('#openCorrection').hidden=!can('correct');$('#correctionDenied').hidden=can('correct');$('#invalidateZone').hidden=!can('registration_invalidate');$('#evidenceForm').hidden=!can('evidence_manage');$('#evidenceDenied').hidden=can('evidence_manage');$('#loadHistory').hidden=!can('history_read');$('#historyDenied').hidden=can('history_read');$('#evidenceForm [name="refs"]').value=evidenceLines(d.evidence_refs);renderList()}
function hideFault(){$('#faultRecovery').hidden=true;$('#retryCommand').hidden=true}
function showFault(title,message,retryable){$('#faultTitle').textContent=title;$('#faultMessage').textContent=message;$('#retryCommand').hidden=!retryable;$('#faultRecovery').hidden=false}
async function openRegistration(id,options={}){try{if(!options.quiet)notice('正在读取登记、快照和允许动作…');state.details=await api('/api/v1/invoice-registrations/'+id);renderDetails();$('#accessRecovery').hidden=true;if(!options.keepRecovery)hideFault();if(!options.quiet)notice('登记已同步；金额和动作均由服务端收敛。','ok')}catch(error){await recover(error)}}
async function recover(error){if(error.status===401||error.status===403){state.pending=null;hideFault();state.listActions=[];if(state.details)state.details.allowed_actions=[];renderList();if(state.details)renderDetails();$$('dialog[open]').forEach(x=>x.close());$('#accessRecovery').hidden=false;notice(error.message+'。页面已退出编辑状态，请刷新权限。','error');return}if(error.status===409&&state.details){$$('dialog[open]').forEach(x=>x.close());showFault('检测到 revision 或命令冲突',error.message+'；旧 revision 没有写入，也不会自动覆盖。',false);await openRegistration(state.details.id,{quiet:true,keepRecovery:true});notice('最新 revision 已载入，请核对后重新提交。','error');return}if(error.status===422){state.pending=null;$$('dialog[open]').forEach(x=>x.close());showFault('输入或来源引用需要核对',error.message+'；本次操作零写入。',false);notice(error.message+'；请检查 Party、来源或文件 revision。','error');return}if(error.status===503){$$('dialog[open]').forEach(x=>x.close());showFault('依赖服务暂时不可用',error.message+'；当前投影与输入保留，本次操作零写入。',!!state.pending);notice('依赖恢复后可使用同一 Command ID 安全重试。','error');return}state.pending=null;notice(error.message+(error.retryable?'，可以稍后重试。':''),'error')}
async function command(path,body,onSuccess){if(state.submitting)return;state.submitting=true;state.pending={path,body,onSuccess};$('#retryCommand').disabled=true;try{notice('正在提交业务动作…');const result=await api(path,{method:path.endsWith('/evidence')?'PUT':'POST',body:JSON.stringify(body)});state.pending=null;hideFault();await onSuccess(result)}catch(error){await recover(error)}finally{state.submitting=false;$('#retryCommand').disabled=false}}
async function finishMutation(result){state.details=result;renderDetails();await loadList();await openRegistration(result.id,{quiet:true});notice('业务动作已完成，当前 revision 为 '+result.revision+'。','ok')}
function sourceFrom(form){const kind=form.get('source_kind');if(kind==='manual_confirmation')return{kind,manual_summary:form.get('manual_summary')};return{kind,resource_id:form.get('source_resource_id'),source_revision:Number(form.get('source_revision'))}}
function parseEvidence(raw){if(!raw.trim())return[];return raw.split('\n').filter(x=>x.trim()).map((line,index)=>{const parts=line.split('|').map(x=>x.trim());if(parts.length<3||!parts[0]||!Number(parts[1])||!['invoice_document','supporting_material'].includes(parts[2]))throw new Error('第 '+(index+1)+' 行 Evidence 格式不正确');return{file_id:parts[0],version:Number(parts[1]),purpose:parts[2],display_name:parts[3]||''}})}
function cookie(name){return document.cookie.split(';').map(x=>x.trim()).find(x=>x.startsWith(name+'='))?.slice(name.length+1)||''}
async function refreshPermissions(){try{notice('正在通过 Gateway 向 IAM 刷新权限…');if(!suiteBase){await loadList();if(state.details)await openRegistration(state.details.id);return}const csrf=decodeURIComponent(cookie('oms_iam_csrf'));if(!csrf)throw new Error('缺少统一入口安全令牌，请返回工作台重新进入');const body=new URLSearchParams({csrf_token:csrf}),project=$('#projectFilter').value.trim()||params.get('project_id')||'';if(project){body.set('resource_type','project');body.set('resource_id',project)}const response=await fetch('/gateway/authorize/billing-invoice',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded','X-CSRF-Token':csrf},body,redirect:'follow'});if(!response.ok){let data={};try{data=await response.json()}catch{}throw errorOf(response,data)}await loadList();if(state.details)await openRegistration(state.details.id);$('#accessRecovery').hidden=true;notice('权限已刷新；撤销后的动作不会继续显示。','ok')}catch(error){recover(error)}}
function setCredentialState(){const suite=!!suiteBase,connected=suite||!!state.token;$('#credentialState').textContent=suite?'Gateway / IAM 短期能力凭证':connected?'本地模板凭证已连接':'尚未连接';$('#openCredential').hidden=suite;$('#refreshPermissions').hidden=!connected;if(params.get('project_id'))$('#projectFilter').value=params.get('project_id');if(connected)loadList()}
function toggleSourceFields(){const manual=$('#createForm [name="source_kind"]').value==='manual_confirmation';$('#manualSummaryField').hidden=!manual;$('#sourceResourceField').hidden=manual;$('#sourceRevisionField').hidden=manual;$('#createForm [name="manual_summary"]').required=manual;$('#createForm [name="source_resource_id"]').required=!manual;$('#createForm [name="source_revision"]').required=!manual}
$$('.tab').forEach(x=>x.onclick=()=>pane(x.dataset.pane));$$('[data-close]').forEach(x=>x.onclick=()=>$('#'+x.dataset.close).close());$('#refreshPermissions').onclick=refreshPermissions;$('#refreshList').onclick=loadList;$('#applyFilters').onclick=loadList;$('#reload').onclick=()=>state.details&&openRegistration(state.details.id);$('#reloadLatest').onclick=()=>state.details&&openRegistration(state.details.id);$('#retryCommand').onclick=()=>{if(state.pending)command(state.pending.path,state.pending.body,state.pending.onSuccess)};
$('#openCredential').onclick=()=>{$('#token').value=state.token;$('#credentialDialog').showModal()};$('#credentialForm').onsubmit=event=>{event.preventDefault();state.token=$('#token').value.trim();sessionStorage.setItem('billing-demo-token',state.token);$('#credentialDialog').close();setCredentialState()};$('#newRegistration').onclick=()=>{$('#createDialog').showModal()};$('#createForm [name="source_kind"]').onchange=toggleSourceFields;$('#createForm').onsubmit=event=>{event.preventDefault();try{const form=event.target,f=new FormData(form),body={command_id:uuid(),issued_on:f.get('issued_on'),amount_minor:toMinor(f.get('amount')),currency:String(f.get('currency')).toUpperCase(),issuer_party_ref:{id:f.get('issuer_id'),revision:Number(f.get('issuer_revision'))},recipient_party_ref:{id:f.get('recipient_id'),revision:Number(f.get('recipient_revision'))},source_refs:[sourceFrom(f)],note:f.get('note')||''};command('/api/v1/invoice-registrations',body,async result=>{$('#createDialog').close();form.reset();toggleSourceFields();await loadList();await openRegistration(result.id)})}catch(error){notice(error.message,'error')}};
$('#openCorrection').onclick=()=>{const d=state.details,form=$('#correctionForm');form.elements.issued_on.value=d.issued_on;form.elements.note.value=d.note||'';$('#correctionAmountField').hidden=!d.amount_visible;form.elements.amount.value=d.amount_visible?minorInput(d.amount_minor):'';form.elements.reason.value='';$('#correctionDialog').showModal()};$('#correctionForm').onsubmit=event=>{event.preventDefault();try{const f=new FormData(event.target),d=state.details,patch={issued_on:f.get('issued_on'),note:f.get('note')||''};if(d.amount_visible)patch.amount_minor=toMinor(f.get('amount'));command('/api/v1/invoice-registrations/'+d.id+'/corrections',{command_id:uuid(),expected_revision:d.revision,reason:f.get('reason'),patch},result=>{$('#correctionDialog').close();finishMutation(result)})}catch(error){notice(error.message,'error')}};
$('#evidenceForm').onsubmit=event=>{event.preventDefault();try{const f=new FormData(event.target),d=state.details;command('/api/v1/invoice-registrations/'+d.id+'/evidence',{command_id:uuid(),expected_revision:d.revision,reason:f.get('reason'),evidence_refs:parseEvidence(f.get('refs'))},finishMutation)}catch(error){notice(error.message,'error')}};$('#openInvalidation').onclick=()=>$('#invalidationDialog').showModal();$('#invalidationForm').onsubmit=event=>{event.preventDefault();const f=new FormData(event.target),d=state.details;command('/api/v1/invoice-registrations/'+d.id+'/invalidation',{command_id:uuid(),expected_revision:d.revision,reason:f.get('reason')},result=>{$('#invalidationDialog').close();finishMutation(result)})};
$('#loadHistory').onclick=async()=>{try{const d=state.details,data=await api('/api/v1/invoice-registrations/'+d.id+'/history?limit=50'),root=$('#historyList');root.replaceChildren();(data.items||[]).forEach(item=>{const row=document.createElement('div'),title=document.createElement('strong'),meta=document.createElement('span'),reason=document.createElement('p');row.className='event';title.textContent=eventLabel[item.event_kind]||item.event_kind;meta.textContent='revision '+item.revision+' · '+fmt(item.occurred_at);reason.textContent=(item.reason||'初始登记')+' · 操作者 '+item.actor_ref;row.append(title,meta,reason);root.append(row)});if(!root.children.length){const empty=document.createElement('div');empty.className='empty';empty.textContent='没有历史记录。';root.append(empty)}notice('历史已读取；旧 snapshot 的金额同样按当前能力收敛。','ok')}catch(error){recover(error)}};
toggleSourceFields();setCredentialState();})();`
